namespace sv_79f5dec3bbb84b6c970a757322efb3ce.Services;

public enum ThemeMode { Light, Dark, System }

/// <summary>
/// Scoped service — one instance per circuit (per user connection).
/// Holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }
}

@* This interactive island lives inside the static layout.
   Because it has its own rendermode, it participates in the circuit
   and can react to ThemeService changes in real time. *@

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="selectedTheme">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="accentColor" @bind:event="oninput" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

<p class="mt-3">
    Current: <strong style="color: @ThemeService.AccentColor;">@ThemeService.Theme</strong>
</p>

@code {
    private Services.ThemeMode selectedTheme;
    private string accentColor = "#0d6efd";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.Theme;
        accentColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnThemeChanged;
    }

    private void Save()
    {
        ThemeService.SetTheme(selectedTheme);
        ThemeService.SetAccentColor(accentColor);
    }

    private void OnThemeChanged()
    {
        selectedTheme = ThemeService.Theme;
        accentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

